function watchedUrls(override) {
  const text = String(override || '').trim();
  if (text) {
    return text.split(',').map(function (part) { return part.trim(); }).filter(Boolean);
  }
  return ['https://example.com/', 'https://example.org/'];
}

if (typeof $input === 'undefined') {
  return { watchedUrls: watchedUrls };
}

const urls = watchedUrls('');
return urls.map(function (url) { return { json: { url: url } }; });

function nextCheckState(previous, ok) {
  const prev = previous && typeof previous === 'object' ? previous : {};
  const prevFailures = Number(prev.consecutiveFailures || 0);
  const prevStatus = prev.status || 'unknown';
  if (ok) {
    const recovered = prevStatus === 'down';
    return {
      consecutiveFailures: 0,
      status: 'up',
      notify: recovered,
      kind: recovered ? 'recovery' : 'none',
    };
  }
  const consecutiveFailures = prevFailures + 1;
  const alert = consecutiveFailures === 2;
  return {
    consecutiveFailures: consecutiveFailures,
    status: consecutiveFailures >= 2 ? 'down' : 'degraded',
    notify: alert,
    kind: alert ? 'down' : 'none',
  };
}

function isHttpOk(json) {
  const value = json && json.statusCode;
  const code = typeof value === 'number' ? value : Number(value || 0);
  return code >= 200 && code < 400;
}

function pairedIndex(item, fallback) {
  const paired = item && item.pairedItem;
  if (paired && typeof paired.item === 'number') return paired.item;
  if (Array.isArray(paired) && paired[0] && typeof paired[0].item === 'number') return paired[0].item;
  return fallback;
}

if (typeof $input === 'undefined') {
  return { nextCheckState: nextCheckState, isHttpOk: isHttpOk };
}

const responses = $input.all();
const sources = $('List Watched URLs').all();
const staticData = $getWorkflowStaticData('global');
if (!staticData.checks || typeof staticData.checks !== 'object') staticData.checks = {};
const out = [];
for (let i = 0; i < responses.length; i++) {
  const response = responses[i];
  const idx = pairedIndex(response, i);
  const source = sources[idx] && sources[idx].json ? sources[idx].json : {};
  const url = source.url || '';
  const ok = isHttpOk(response.json || {});
  const next = nextCheckState(staticData.checks[url], ok);
  staticData.checks[url] = {
    consecutiveFailures: next.consecutiveFailures,
    status: next.status,
  };
  out.push({
    json: {
      url: url,
      httpStatus: (response.json && response.json.statusCode) || 0,
      consecutiveFailures: next.consecutiveFailures,
      status: next.status,
      notify: next.notify ? 'yes' : 'no',
      kind: next.kind,
      subject: 'Uptime ' + next.kind + ' ' + url,
      text: 'URL ' + url + ' is ' + next.status + ' after ' + next.consecutiveFailures + ' consecutive failures.',
    },
  });
}
return out;
